select id, title, original_title, cover, type, genre, episodes, status, year, rating, synopsis, created_at, updated_at
from anime


        AND title LIKE CONCAT('%', #{title}, '%')


        AND type = #{type}


        AND status = #{status}


ORDER BY id DESC
